mapper.select:
SELECT  FROM ai_conversation
 WHERE user_id = #{userId}
 ORDER BY updated_at DESC, id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT id, user_id AS userId, conversation_id AS conversationId, idempotency_key AS idempotencyKey,
       message_id AS messageId, generation_id AS generationId, mode, provider_id AS providerId,
       provider_name AS providerName, model_id AS modelId, reasoning_effort AS reasoningEffort,
       state, error_code AS errorCode, error_message AS errorMessage, started_at AS startedAt,
       finished_at AS finishedAt, duration_ms AS durationMs, input_chars AS inputChars,
       output_chars AS outputChars, prompt_tokens AS promptTokens, completion_tokens AS completionTokens
  FROM ai_chat_run
 WHERE user_id = #{userId}
 AND state = #{state}
 AND provider_id = #{providerId}
 AND model_id = #{modelId}
 AND started_at >= #{since}
 ORDER BY started_at DESC, id DESC
 LIMIT #{limit} OFFSET #{offset}

mapper.sql:
 WHERE user_id = #{userId}
   AND started_at >= #{since}
AND provider_id = #{providerId}
AND model_id = #{modelId}

mapper.select:
SELECT provider_id AS providerId, provider_name AS providerName, model_id AS modelId,
       COUNT(*) AS runs,
       COALESCE(SUM(state = 'FAILED'), 0) AS failed,
       COALESCE(SUM(prompt_tokens), 0) AS promptTokens,
       COALESCE(SUM(completion_tokens), 0) AS completionTokens,
       COALESCE(SUM(duration_ms), 0) AS durationMs
  FROM ai_chat_run
 WHERE user_id = #{userId} AND started_at >= #{since}
AND provider_id = #{providerId}
AND model_id = #{modelId}
 GROUP BY provider_id, provider_name, model_id
 ORDER BY runs DESC, model_id
 LIMIT #{limit}

SELECT COUNT(*) FROM ai_chat_run WHERE user_id = #{userId}
AND state = #{state}
AND provider_id = #{providerId}
AND model_id = #{modelId}
AND started_at >= #{since}
